var InvoiceStore=(()=>{
let opening;function db(){return opening||=new Promise((resolve,reject)=>{if(!globalThis.indexedDB){reject(Error('Dieser Browser unterstützt die lokale Belegspeicherung nicht.'));return}const r=indexedDB.open('immobrain-invoices-v1',1);r.onupgradeneeded=()=>{r.result.createObjectStore('invoices',{keyPath:'id'});r.result.createObjectStore('files',{keyPath:'id'})};r.onsuccess=()=>{r.result.onversionchange=()=>r.result.close();resolve(r.result)};r.onerror=()=>{opening=null;reject(Error('Belegspeicher konnte nicht geöffnet werden.'))};r.onblocked=()=>reject(Error('Bitte weitere geöffnete ImmoBrain-Tabs schließen.'))})}
async function transaction(stores,mode,run){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction(stores,mode);let value;try{value=run(tx)}catch(e){tx.abort();reject(e);return}tx.oncomplete=()=>resolve(typeof value==='function'?value():value);tx.onerror=tx.onabort=()=>reject(Error('Belegspeicherung fehlgeschlagen. Bitte Speicherplatz und Browserberechtigungen prüfen.'))})}
function get(store,id){return transaction([store],'readonly',tx=>{const r=tx.objectStore(store).get(id);return ()=>r.result})}
return {all:()=>transaction(['invoices'],'readonly',tx=>{const r=tx.objectStore('invoices').getAll();return ()=>r.result}),get:id=>get('invoices',id),file:async id=>(await get('files',id))?.file,add:(meta,file)=>transaction(['invoices','files'],'readwrite',tx=>{tx.objectStore('invoices').add(meta);tx.objectStore('files').add({id:meta.id,file})}),put:meta=>transaction(['invoices'],'readwrite',tx=>tx.objectStore('invoices').put(meta)),remove:id=>transaction(['invoices','files'],'readwrite',tx=>{tx.objectStore('invoices').delete(id);tx.objectStore('files').delete(id)})};})();
